      driverUrl: ' http://127.0.0.1:39117/ ',
      printCount: 5,
    );

    expect(request.toJson(), {
      'batch_id': 'batch-1',
      'expected_revision': 7,
      'expected_item_code': 'ITEM-1',
      'expected_warehouse': 'Stores - A',
      'gross_qty': 2.5,
